#include<stdio.h>


#define SRAM_START 				0x20000000U
#define SRAM_SIZE  				(128 * 1024)
#define SRAM_END  				( (SRAM_START) + (SRAM_SIZE) )
#define STACK_START SRAM_END

#define STACK_MSP_START 		STACK_START
#define STACK_MSP_END   		(STACK_MSP_START - 512)
#define STACK_PSP_START 		STACK_MSP_END


int fun_add(int a, int b , int c , int d)
{
	return a+b+c+d;
}


/* this function changes SP to PSP */
__attribute__((naked)) void change_sp_to_psp(void)
{
	/*
	 * Standard C Definitions cannot be used in the ASM Language
	 * For that we are using ".equ" in the ASM
	 *
	 * attribute((naked)) — Compiler directive meaning "do NOT add any extra code
	 * naked — The function body contains ONLY raw assembly (no auto-generated save/restore code)
	 *
	 * Why used? — Naked functions are needed when writing pure assembly, because normal functions would automatically save/restore registers, which would interfere.
	 */
	__asm volatile(".equ SRAM_END, (0x20000000 + ( 128 * 1024))");
	__asm volatile(".equ PSP_START , (SRAM_END-512)");
	__asm volatile("LDR R0,=PSP_START");
	__asm volatile("MSR PSP, R0");
	__asm volatile("MOV R0,#0X02");
	__asm volatile("MSR CONTROL,R0");
	__asm volatile("BX LR");
	/*
	 * When we jump from main to Change_sp_to_psp, The LR is the register which captures the return address,
	 * LR Knows where to go back when this function finishes.
	 */

}

void generate_exception(void)
{
	/* execute SVC instruction to cause SVC exception
	 * SVC — "Supervisor Call" (a software-generated exception/interrupt)
	 * #0x2 — Exception number 2 (a label; the handler doesn't care about this number)
	 * */


	__asm volatile("SVC #0X2");
}

int main(void)
{
	change_sp_to_psp();

/* from here onwards PSP will be used for stack activities */
	int ret;

	ret = fun_add(1, 4, 5, 6);

	printf("result = %d\n",ret);

	generate_exception();

	for(;;);
}


void SVC_Handler(void)
{
	printf(" in SVC_Handler\n");
}
